// =========================================================================
// Filtre J-30 / J-14 / J-7 pour NOËL (25 décembre).
// Noël est commun à tous les proches : on calcule le prochain 25/12 (si déjà
// passé cette année, l'année suivante) et on ne conserve que les événements
// dont le nombre de jours restants vaut exactement 30, 14 ou 7.
// =========================================================================

const SEUILS = [30, 14, 7];
const MS_PAR_JOUR = 1000 * 60 * 60 * 24;

const aujourdhui = new Date();
aujourdhui.setHours(0, 0, 0, 0);

// Prochain 25 décembre.
const annee = aujourdhui.getFullYear();
let noel = new Date(annee, 11, 25);
noel.setHours(0, 0, 0, 0);
if (noel < aujourdhui) noel = new Date(annee + 1, 11, 25);

const joursRestants = Math.round((noel - aujourdhui) / MS_PAR_JOUR);

// Si on n'est pas à un seuil, aucun e-mail Noël à envoyer aujourd'hui :
// on coupe court en ne renvoyant rien.
if (!SEUILS.includes(joursRestants)) return [];

const dateNoel = noel.toISOString().slice(0, 10);
const sortie = [];
for (const item of $input.all()) {
  sortie.push({
    json: {
      ...item.json,
      jours_restants: joursRestants,
      date_evenement: dateNoel,
    },
  });
}
return sortie;

// Assemble l'e-mail (template §9) + le payload de log à partir de
// l'événement enrichi, des propositions scorées et des détails produits.
// Type fixe ici : 'noel'.

const ev = $('Filtre J-30 / J-14 / J-7').item.json;
const propositions = $('Edge Function matching').item.json.propositions || [];
const produits = $input.item.json.data || $input.item.json || [];

const parId = {};
for (const p of produits) parId[p.id] = p;

const prenomUtilisateur = ev.proches?.profils?.prenom || '';
const prenomProche = ev.proches?.prenom || '';
const jours = ev.jours_restants;

function formatPrix(p) {
  const min = p.prix_min != null ? Math.round(p.prix_min) : null;
  const max = p.prix_max != null ? Math.round(p.prix_max) : null;
  if (min != null && max != null) return min === max ? `${min} €` : `${min}–${max} €`;
  if (min != null) return `dès ${min} €`;
  if (max != null) return `jusqu'à ${max} €`;
  return '';
}

const lignesHtml = [];
const lignesLog = [];
for (const prop of propositions.slice(0, 5)) {
  const produit = parId[prop.produit_id];
  if (!produit) continue;
  const prix = formatPrix(produit);
  lignesHtml.push(
    `<li style="margin:8px 0"><a href="${produit.url_produit}">${produit.nom}</a>${prix ? ` — <strong>${prix}</strong>` : ''}</li>`
  );
  lignesLog.push({ proche_id: ev.proche_id, evenement_id: ev.id, produit_id: prop.produit_id, score: prop.score });
}

const lienApp = $env.APP_URL || 'https://giftmatch.app';
const sujet = `🎁 Idées cadeaux pour ${prenomProche} — Noël dans ${jours} jours`;
const html = `
<div style="font-family:system-ui,Arial,sans-serif;color:#222;max-width:560px">
  <p>Bonjour ${prenomUtilisateur},</p>
  <p><strong>Noël</strong> approche pour ${prenomProche} !<br>Voici 5 idées sélectionnées pour lui/elle :</p>
  <ul style="list-style:none;padding:0">${lignesHtml.join('')}</ul>
  <p><a href="${lienApp}">Voir d'autres idées →</a></p>
</div>`.trim();

return [{
  json: {
    sujet,
    html,
    destinataire_email: ev.proches?.profils?.email || $env.RESEND_FALLBACK_TO || '',
    lignes_log: lignesLog,
    a_envoyer: lignesLog.length > 0,
  },
}];
